#include <stdio.h>

int main(void) {
    int x = 10;

    while (x < 5) {
        printf("while ran\n");
    }

    do {
        printf("do-while ran\n");
    } while (x < 5);

    return 0;
}

#include <stdio.h>

int main(void) {
    int age;

    do {
        printf("Enter your age (1-120): ");
        scanf("%d", &age);
    } while (age < 1 || age > 120);

    printf("Thanks! You are %d.\n", age);
    return 0;
}

#include <stdio.h>

int main(void) {
    int choice;
    int balance = 500;

    do {
        printf("\n1. Check balance\n2. Add 100\n3. Exit\n");
        printf("Choice: ");
        scanf("%d", &choice);

        if (choice == 1) {
            printf("Balance: %d\n", balance);
        } else if (choice == 2) {
            balance = balance + 100;
            printf("Added! Balance: %d\n", balance);
        } else if (choice != 3) {
            printf("Invalid choice\n");
        }
    } while (choice != 3);

    printf("Bye!\n");
    return 0;
}
